import{_ as e,o as a,c as r,a5 as s}from"./chunks/framework.CXroN2RO.js";const n="/study/images/graphics/models-and-meshes.svg",p=JSON.parse('{"title":"モデルとメッシュの基本 — 頂点から形を作る","description":"","frontmatter":{"title":"モデルとメッシュの基本 — 頂点から形を作る","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"キャラクターや箱の形を例に、モデル、メッシュ、頂点、辺、面、三角形、インデックス、法線の役割を説明する。","aliases":["3Dモデル","モデル","メッシュ","mesh","頂点","vertex","辺","edge","面","face","ポリゴン","三角形","インデックス","法線","normal"],"verification":"Unityのメッシュデータ資料、Blenderのメッシュ構造の説明とKhronosのglTF 2.0仕様に照合（2026-11-07）"}},"headers":[],"relativePath":"graphics/basics/models-and-meshes.md","filePath":"graphics/basics/models-and-meshes.md"}'),o={name:"graphics/basics/models-and-meshes.md"};function d(h,t,i,l,m,g){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="モデルとメッシュの基本-—-頂点から形を作る" tabindex="-1">モデルとメッシュの基本 — 頂点から形を作る <a class="header-anchor" href="#モデルとメッシュの基本-—-頂点から形を作る" aria-label="Permalink to &quot;モデルとメッシュの基本 — 頂点から形を作る&quot;">​</a></h1><p>ゲームに登場するキャラクターや箱は、形のデータを使って描きます。<strong>3Dモデル</strong>という言葉は、形に加え、見た目や動かすための情報を含む素材を指すこともあります。そのうち、点や面のつながりで形を表すものが<strong>メッシュ</strong>です。一つのモデルに、体や装備など複数のメッシュを含められます。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/mesh-introduction.html" target="_blank" rel="noreferrer">Unityのメッシュ入門</a></p><h2 id="点を置き、辺と面でつなぐ" tabindex="-1">点を置き、辺と面でつなぐ <a class="header-anchor" href="#点を置き、辺と面でつなぐ" aria-label="Permalink to &quot;点を置き、辺と面でつなぐ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用語</th><th>何を表すか</th><th>箱を考える例</th></tr></thead><tbody><tr><td><strong>頂点</strong></td><td>形を構成する点。3Dでは位置を通常三つの座標で表す。</td><td>箱の角にある点。</td></tr><tr><td><strong>辺</strong></td><td>頂点同士のつながり。</td><td>角と角を結ぶ線。</td></tr><tr><td><strong>面・ポリゴン</strong></td><td>複数の辺で囲む表面の部分。</td><td>箱の上面や側面。</td></tr><tr><td><strong>三角形</strong></td><td>三つの頂点で作る面。</td><td>四角い面を対角線で分けた二つの面。</td></tr></tbody></table><p>モデリングツールでは四角形や、さらに多くの頂点を持つ面も編集できます。ゲームの一般的な三角形描画へ渡す際は、そうした面を三角形へ分けます。この処理を<strong>三角形化</strong>と呼びます。描画方式によっては線や点なども使うため、メッシュのデータを読むときは、どの単位で組み立てるかも確認します。<a href="https://docs.blender.org/manual/en/4.0/modeling/meshes/structure.html" target="_blank" rel="noreferrer">Blenderの頂点・辺・面</a> · <a href="https://docs.unity.com/en-us/engine/6000.0/manual/assets-and-media/asset-types/mesh/get-started-with-meshes/anatomyofa/topology-data" target="_blank" rel="noreferrer">Unityのメッシュのトポロジー</a></p><h2 id="頂点番号で三角形を指定する" tabindex="-1">頂点番号で三角形を指定する <a class="header-anchor" href="#頂点番号で三角形を指定する" aria-label="Permalink to &quot;頂点番号で三角形を指定する&quot;">​</a></h2><p>四つの頂点に<code>0</code>から<code>3</code>の番号を付けます。三角形を作る頂点番号を並べたものが<strong>インデックス</strong>です。例えば<code>0, 1, 2</code>で一つ、<code>0, 2, 3</code>でもう一つの三角形を作れば、四角い面を表せます。番号0と2は両方の三角形で再利用できます。<a href="https://docs.unity.com/en-us/engine/6000.0/manual/assets-and-media/asset-types/mesh/get-started-with-meshes/anatomyofa/index-data" target="_blank" rel="noreferrer">Unityのインデックスデータ</a></p><figure class="study-figure"><img src="'+n+'" alt="四角形の頂点に左下から0、1、2、3と番号を付ける。0・1・2と0・2・3の二つの三角形を指定し、同じ位置のデータを共有する。頂点には位置のほか、法線やUVなどの属性を付けられる。" width="760" height="460" loading="lazy"><figcaption>位置と番号を使って形を表す説明用の例です。<a href="/study/images/graphics/models-and-meshes.svg" target="_blank" rel="noopener noreferrer">頂点と三角形の図を拡大</a></figcaption></figure><p>頂点の並び順も描画の設定に使います。片側だけを描く設定では、三角形をどちらから見ているかによって描画されるかが変わります。形があるのに片側から消える場合は、面の向きと描画設定を調べます。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#meshes" target="_blank" rel="noreferrer">KhronosのglTFのメッシュ仕様</a> · <a href="/study/graphics/pipeline/rasterization.html">ラスタライゼーション</a></p><h2 id="頂点には位置以外の情報もある" tabindex="-1">頂点には位置以外の情報もある <a class="header-anchor" href="#頂点には位置以外の情報もある" aria-label="Permalink to &quot;頂点には位置以外の情報もある&quot;">​</a></h2><p>描画で使う頂点には、位置だけでなく、次のような<strong>属性</strong>を持たせられます。使う属性はメッシュや描画方法によって変わります。<a href="https://docs.unity.com/en-us/engine/6000.0/manual/assets-and-media/asset-types/mesh/get-started-with-meshes/anatomyofa/vertex-data" target="_blank" rel="noreferrer">Unityの頂点データ</a></p><table tabindex="0"><thead><tr><th>属性</th><th>主な用途</th></tr></thead><tbody><tr><td><strong>位置</strong></td><td>頂点をどこに置くか。</td></tr><tr><td><strong>法線</strong></td><td>表面の向きを表し、光の反射などの計算に使う。</td></tr><tr><td><strong>UV</strong></td><td>テクスチャのどの場所を表面へ対応させるか。</td></tr><tr><td><strong>頂点色</strong></td><td>頂点に付けた色を、描画の計算に使う。</td></tr></tbody></table><p><strong>法線</strong>は向きを表す値です。面の向きにそろえた法線を使うと面ごとの境界が見えやすく、つながる面の法線をなめらかに変化させると丸みがあるように見せられます。法線による見た目の変化と、頂点位置を動かして輪郭を変える操作は、それぞれ役割が異なります。<a href="https://docs.unity.com/en-us/engine/6000.0/manual/assets-and-media/asset-types/mesh/get-started-with-meshes/anatomyofa/vertex-data#normal" target="_blank" rel="noreferrer">Unityの頂点法線</a></p><h2 id="同じ角に複数の頂点を置くことがある" tabindex="-1">同じ角に複数の頂点を置くことがある <a class="header-anchor" href="#同じ角に複数の頂点を置くことがある" aria-label="Permalink to &quot;同じ角に複数の頂点を置くことがある&quot;">​</a></h2><p>立方体の角は幾何学的には一か所でも、面ごとに異なる法線を使って硬い境目を作る場合があります。描画用の一つの頂点番号で位置と法線などをまとめて選ぶ形式では、その角に位置が同じで法線が違う頂点を用意します。UVのつなぎ目も、位置が同じで別のUVを持つ例です。モデリングツールの点の数と、書き出した描画用頂点の数が変わることがあります。<a href="/study/graphics/mesh/vertex-and-index-input.html">頂点属性とインデックスの詳細</a> · <a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#meshes" target="_blank" rel="noreferrer">Khronosの頂点属性とインデックス</a></p><h2 id="ゲームに置くときに足すもの" tabindex="-1">ゲームに置くときに足すもの <a class="header-anchor" href="#ゲームに置くときに足すもの" aria-label="Permalink to &quot;ゲームに置くときに足すもの&quot;">​</a></h2><p>メッシュを使う物体は、シーン内での位置や向き、見た目、動作なども持ちます。同じメッシュを使い、位置や材質を変えた複数の箱を置くこともできます。<a href="/study/game/basics/scenes-and-components.html">シーンとコンポーネント</a></p><p>配置の基本は<a href="/study/graphics/basics/transforms-and-cameras.html">座標変換とカメラ</a>、表面の見た目は<a href="/study/graphics/basics/materials-textures-and-shaders.html">マテリアル・テクスチャ・シェーダー</a>へ進みます。ファイルから実際のデータを取り出す方法は、<a href="/study/graphics/mesh/gltf-mesh-buffers.html">glTFのメッシュバッファ</a>で扱います。</p>',18)])])}const u=e(o,[["render",d]]);export{p as __pageData,u as default};
